sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float direction;
half4 main(float2 coord) {
    float2 c = size * 0.5;
    float r = 0.5 * min(size.x, size.y);
    float2 q;
    if (direction < 0.5) {
        float2 d = coord - c;
        float t = (dot(d, d) > 0.0 ? atan(d.x, -d.y) : 0.0) / 6.2831853 + 0.5;
        q = float2(t * size.x, length(d) / r * size.y);
    } else {
        float t = (coord.x / size.x - 0.5) * 6.2831853;
        float k = coord.y / size.y * r;
        q = c + float2(sin(t), -cos(t)) * k;
    }
    float2 at = mix(coord, q, clamp(amount, 0.0, 1.0));
    if (at.x < 0.0 || at.y < 0.0 || at.x > size.x || at.y > size.y) return half4(0.0);
    return image.eval(at);
}
